import FanbasisCheckout from '@fanbasis/checkout-sdk';

const client = new FanbasisCheckout({
  apiKey: process.env['FANBASIS_CHECKOUT_API_KEY'], // This is the default and can be omitted
});

const response = await client.checkoutSessions.subscriptions.cancel('subscriptionId', {
  checkoutSessionId: 'checkoutSessionId',
});

console.log(response.data);

